function divideStrict(a, b) {
  if (typeof a !== "number" || typeof b !== "number") throw "Numbers required";
  if (b === 0) throw "Division by zero";
  return a / b;
}

function loadAll(loaders, log) {
  let done = 0;
  try {
    for (const l of loaders) {
      l();
      done++;
    }
    return done;
  } finally {
    log.push("total: " + done);
    return done;
  }
}
